command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
Set-Location -LiteralPath $repo
& git fetch origin --prune --no-tags
if($LASTEXITCODE -ne 0){throw "fetch failed"}
& git diff --quiet refs/remotes/origin/main refs/remotes/origin/work/failure-propagation-20261005 --
if($LASTEXITCODE -ne 0){throw "merged work branch tree differs from main"}
& git push origin --delete "validate/failure-propagation-product-contract-20261005" "validate/native-preflight-selected-20261005" "validate/native-preflight-selected-v2-20261005" "validate/native-preflight-selected-v3-20261005" "work/failure-propagation-20261005" "work/failure-propagation-native-preflight-20261005"
if($LASTEXITCODE -ne 0){throw "branch deletion failed"}
& git fetch origin --prune --no-tags
if($LASTEXITCODE -ne 0){throw "post-delete fetch failed"}
  if(& git show-ref --verify --quiet "refs/remotes/origin/validate/failure-propagation-product-contract-20261005"){throw "branch still exists: validate/failure-propagation-product-contract-20261005"}
  if(& git show-ref --verify --quiet "refs/remotes/origin/validate/native-preflight-selected-20261005"){throw "branch still exists: validate/native-preflight-selected-20261005"}
  if(& git show-ref --verify --quiet "refs/remotes/origin/validate/native-preflight-selected-v2-20261005"){throw "branch still exists: validate/native-preflight-selected-v2-20261005"}
  if(& git show-ref --verify --quiet "refs/remotes/origin/validate/native-preflight-selected-v3-20261005"){throw "branch still exists: validate/native-preflight-selected-v3-20261005"}
  if(& git show-ref --verify --quiet "refs/remotes/origin/work/failure-propagation-20261005"){throw "branch still exists: work/failure-propagation-20261005"}
  if(& git show-ref --verify --quiet "refs/remotes/origin/work/failure-propagation-native-preflight-20261005"){throw "branch still exists: work/failure-propagation-native-preflight-20261005"}
Write-Host "FAILURE_PROPAGATION_BRANCH_CLEANUP=PASS"
